import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"NVMe oFgateway for Ceph Developer Summit - Vampire","description":"","frontmatter":{"title":"NVMe oFgateway for Ceph Developer Summit - Vampire","date":"2026-08-14T00:00:00.000Z","updated":"2026-08-15T00:00:00.000Z","tags":["Ceph","NVMe","iSCSI","高可用性","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/NVMe_oFgateway_for_Ceph_Developer_Summit_-_Vampire.md","filePath":"posts/2026/NVMe_oFgateway_for_Ceph_Developer_Summit_-_Vampire.md","lastUpdated":null}'),i={name:"posts/2026/NVMe_oFgateway_for_Ceph_Developer_Summit_-_Vampire.md"};function s(p,e,n,c,l,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次会议是 Ceph Developer Summit Vampire 版本的 NVMe-oF Gateway 专项会议，由 Aviv、Leonid（Luanit）和 Alex 等核心开发人员主讲，重点介绍了 Vampire 版本中 NVMe-oF Gateway 的几项重大特性规划和当前开发进展。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="一、active-active-支持-核心特性" tabindex="-1">一、Active-Active 支持（核心特性） <a class="header-anchor" href="#一、active-active-支持-核心特性" aria-label="Permalink to &quot;一、Active-Active 支持（核心特性）&quot;">​</a></h3><p><strong>背景</strong></p><p>当前 NVMe-oF Gateway 采用 per-namespace 的 active-standby 模式。在此模式下，每个 namespace 在任意时刻仅由一个 gateway 提供服务。实现机制是通过 ANA（Asymmetric Namespace Access）groups 来管理：gateway 数量决定 ANA group 数量，每个 ANA group 在某一 gateway 上处于 optimized 状态，在其他 gateway 上处于 inaccessible 状态，强制 initiator 通过特定 gateway 访问特定 namespace。</p><p><strong>Active-Active 的挑战</strong></p><ol><li><p><strong>Failover 处理</strong>：active-active 模式下，host 可能同时通过多个 gateway 向同一 namespace 发送 IO，failover 时需协调所有 gateway，防止数据损坏和写入重排序（write reordering）。</p></li><li><p><strong>Stretch Cluster 支持</strong>：Tentacle 版本已支持 stretch cluster 模式（gateway 具有 locality 属性），active-active 下需继续支持，增加了设计复杂度。</p></li><li><p><strong>模式兼容性</strong>：需同时支持 active-active 和 active-passive 两种模式，并讨论是否允许在运行时切换。</p></li><li><p><strong>Auto Load Balancing</strong>：active-standby 下 load balancing 通过在 ANA groups 之间迁移 namespace 来均衡负载。但在 active-active 下，所有 gateway 始终处于 optimized 状态，host 会 round-robin 分发 IO，namespace 在 ANA groups 之间的分布对负载均衡影响降低。对于 stretch cluster 场景，可能仍需按 site 保持 namespace 数量均衡。</p></li><li><p><strong>Reservation 支持</strong>：当前 reservation 确认机制可能存在问题——active-active 下需确保所有 gateway 都收到并确认 reservation 请求。</p></li><li><p><strong>CLI / Dashboard API 变更</strong>：active-active 特性涉及大量 CLI 和 dashboard API 的修改。</p></li></ol><p><strong>ANA Group 简化方案讨论</strong></p><p>会议中 Ilya 提出：在纯 active-active 模式下，所有 gateway 对所有 namespace 均为 optimized，ANA group 的语义变得模糊，是否可以统一使用单一 ANA group？stretch cluster 场景下可按 site 设置两个 ANA group。Aviv 认可该方案，可显著降低 active-active 实现复杂度。</p><h3 id="二、active-active-failover-架构-leonid-分享" tabindex="-1">二、Active-Active Failover 架构（Leonid 分享） <a class="header-anchor" href="#二、active-active-failover-架构-leonid-分享" aria-label="Permalink to &quot;二、Active-Active Failover 架构（Leonid 分享）&quot;">​</a></h3><p>Failover 流程分为两个阶段：</p><p><strong>阶段一：Fencing Phase</strong></p><p>当检测到某 gateway 宕机时，monitor 向所有 gateway 广播携带 &quot;hold on&quot; 高优先级 bit 的新 map。各 gateway 收到后通过 gRPC 指示 SPDK 发起 transient hold on RPC，将待处理 IO 暂存于 QP buffer 中（而非将 ANA group 切换为 inaccessible，后者效率更低且会导致 host 立即超时）。Monitor 通过 beacon（每秒一次的心跳）的 epoch 确认所有 gateway 均已执行该指令。</p><p><strong>阶段二：Failover Candidate 选择与恢复</strong></p><p>Monitor 选定 failover candidate 后，对宕机 gateway 的所有 namespace cluster context 执行 OSD blocklist。完成 blocklist 后，下发新 map 并清除 &quot;hold on&quot; bit。各 gateway 收到新 map 后：等待所有相关 cluster context 的最新 OSD epoch 同步到位（通常仅需毫秒级），调用 SPDK 禁用 transient hold 并排空 IO 队列，最后应用新的 ANA IO path map。Monitor 通过 beacon 确认各 gateway 完成上述步骤后，将 failover 标记为完成。</p><p><strong>验证情况</strong></p><p>该方案的 PoC 已完成，在持续 IO 负载下验证超过 1,000 次自动 failover/failback 循环，未发现 IO 错误或丢失。本地测试环境中，从发出 transient hold 到 OSD map 发布完成约需 2~3 秒。</p><p><strong>风险点</strong>：整个 failover 流程须在 host 超时之前完成，这是当前的核心假设，也是待解决的开放性问题。此外，leader election 发生时可能阻断 failover 流程，需要额外的处理逻辑。</p><h3 id="三、spdk-batch-ana-state-rpc-优化" tabindex="-1">三、SPDK Batch ANA State RPC 优化 <a class="header-anchor" href="#三、spdk-batch-ana-state-rpc-优化" aria-label="Permalink to &quot;三、SPDK Batch ANA State RPC 优化&quot;">​</a></h3><p>当前设置 ANA state 时，每个 subsystem × listener × ANA state 组合均需发送独立的 RPC。在 100 个 subsystem、8 个 gateway（8 个 ANA group）、每 gateway 多个 listener 的场景下，RPC 调用次数可超过 1,000 次，耗时约 2 秒。</p><p><strong>优化方案</strong>：在 SPDK 层新增批量 RPC 接口，一次性传入 ANA group 数组和对应的新状态数组，对所有 subsystem 统一设置。预计可将耗时从 2 秒降至毫秒级。该优化独立于 active-active，active-passive 模式同样受益。</p><h3 id="四、threading-rework-alex-分享" tabindex="-1">四、Threading Rework（Alex 分享） <a class="header-anchor" href="#四、threading-rework-alex-分享" aria-label="Permalink to &quot;四、Threading Rework（Alex 分享）&quot;">​</a></h3><p><strong>问题描述</strong></p><p>当前 NVMe-oF Gateway 存在两套线程体系：SPDK reactor threads（运行在 SPDK 分配的专用核心上）和 librbd/RADOS 线程池（每个 RADOS 连接独立的线程池）。IO 路径在两套线程间频繁切换，造成 CPU cache 数据迁移和上下文切换开销。此外，为达到最优性能，当前需要开启数十个 RADOS cluster 连接，连接数难以精确调优。</p><p><strong>设计目标</strong></p><ul><li>统一为单一 SPDK reactor threads 集合，从 SPDK 到 librados 全路径运行于同一线程域</li><li>最终降至单一 RADOS cluster 连接</li><li>减少线程上下文切换和 CPU cache 颠簸，提升性能</li></ul><p><strong>实现方案</strong>（Bill Scales 提出）</p><p>在 librbd 层提取纯 C++ 的 <code>ContextWorkQueue</code> 接口（支持 post、dispatch、串行/并行执行、fork/completion 等操作），默认实现映射到原有 boost 风格的 context work queue。在 SPDK 侧实现基于 SPDK reactor 的 <code>ContextWorkQueue</code>，将 post/dispatch 请求转发至 reactor thread 执行。RBD image open 时注入 SPDK work queue，使 librbd 热路径（object image dispatch、QoS、completion 等）路由至 SPDK reactor threads 执行，通过 per-reactor ring 传递消息。</p><p><strong>当前状态</strong></p><p>librbd 热路径已部分重定向至 reactor threads，但 new RADOS IO 仍运行在独立 IO context，全 IO 路径尚未完全统一。正在进行大量性能测试以识别瓶颈并持续优化。</p><h3 id="五、其他待完成事项" tabindex="-1">五、其他待完成事项 <a class="header-anchor" href="#五、其他待完成事项" aria-label="Permalink to &quot;五、其他待完成事项&quot;">​</a></h3><p><strong>Gateway 启动时间优化</strong></p><p>当 namespace 数量达到数百个时，gateway 启动可能需要数分钟。主要耗时在创建 RBD image 对象阶段。Ilya 建议并行化该过程，计划在后续版本中实现。</p><p><strong>Cephadm 集成改进（OK-to-stop）</strong></p><p>当前 cephadm 在 redeploy gateway 时，仅检查进程是否启动，不等待 gateway 完全就绪（subsystem、namespace、listener 初始化完成）。这可能导致滚动重启期间短暂无法接受 IO 的窗口期。</p><p><strong>方案</strong>：在 NVMe monitor 实现 <code>ok-to-stop</code> 命令，确保同一时刻最多只有一个 gateway 处于停止状态，待新 gateway 完全就绪后再允许停止下一个。当前 PR 已基本就绪，待与 Cephadm 集成。</p><p><strong>XCOPY（VMware 跨 namespace 数据迁移）</strong></p><p>VMware 使用 XCOPY 命令在 datastore 间迁移数据的功能已基本实现。发现一个待排查问题：VMware 在某些情况下将 XCOPY 命令发送至处于 inaccessible 路径的 destination namespace（source 和 destination 均在 optimized 路径时功能正常）。计划向 VMware 提交 ticket 并进行联合排查。</p><p><strong>BYOK（Bring Your Own Key）加密 Namespace</strong></p><p>支持创建加密 namespace，使用 RBD image 加密，允许为每个 subsystem 指定 KMIP 端点以获取 passphrase。实现了 KMIP client 集成，并处理了无法获取 passphrase 时的降级场景（创建 degraded namespace 而非终止整个 gateway）。</p><p><strong>文档改进</strong></p><p>现有上游文档未能反映当前实际支持能力，列为 action item，需在 Vampire 版本中完善。</p><h2 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h2><ul><li>Active-Active 和 active-passive 模式将同时支持，用户可选择</li><li>单 ANA group 方案（纯 active-active 场景）作为有效选项继续评估</li><li>Failover 流程基于 SPDK transient hold RPC 实现，已通过 PoC 验证</li><li>SPDK batch ANA state RPC 优化作为独立改进推进</li></ul><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>负责人</th><th>状态</th></tr></thead><tbody><tr><td>Active-Active failover 完整实现</td><td>Leonid</td><td>进行中</td></tr><tr><td>SPDK batch set ANA state RPC</td><td>Leonid</td><td>规划中</td></tr><tr><td>Threading rework 性能测试与优化</td><td>Alex</td><td>进行中</td></tr><tr><td>Gateway 启动并行化</td><td>待定</td><td>规划中</td></tr><tr><td>OK-to-stop 与 Cephadm 集成</td><td>Aviv</td><td>PR 就绪待集成</td></tr><tr><td>XCOPY VMware 问题排查</td><td>Aviv + VMware</td><td>下周提 ticket</td></tr><tr><td>上游文档更新</td><td>团队</td><td>Action Item</td></tr></tbody></table>',47)])])}const m=t(i,[["render",s]]);export{h as __pageData,m as default};
